"""The HGNC alias table: our gene symbols, their HGNC IDs, and the other HGNC names of those IDs.

``data/external/vendor_assay_tables/hgnc_aliases.tsv`` is generated by stage ``vendor_assay_tables``
(``analysis/external/vendor_assay_tables.py``) from the pinned HGNC complete set (``HGNC_URL``, monthly
release 2026-09-04, SHA-256 ``HGNC_SHA256``, fetched into ``HGNC_PATH`` on first use) and our gene symbols
(the annotation's genes, which are the HGNC symbols UniProt 2026_03 records). Our symbols take their HGNC IDs from
the release alone (``symbol_ids_from_hgnc``); the update-layer generator checks that these equal the IDs
UniProt's cross-references record. One row per name:

* ``symbol``: one of our gene symbols and its HGNC ID (the annotation's ``HGNC_ID``);
* ``approved``: HGNC's current approved symbol of one of our IDs, where it differs from ours;
* ``previous``: a previous HGNC symbol of exactly one HGNC ID, one of ours;
* ``alias``: an HGNC alias symbol of exactly one HGNC ID, one of ours, that is no approved or previous
  symbol;
* ``ambiguous``: a previous or alias symbol of several IDs, at least one ours (``hgnc_id`` lists them,
  ``symbol`` is empty); left as it is.

A name resolves in that order: our symbol, then an approved symbol (so a name that is another gene's
approved symbol is never translated), then previous symbols, then aliases (Oh 2020, HGNChelper; limma
``alias2SymbolTable``). Matching ignores case, because Enrichr upper-cases every symbol (C1ORF56 for our
C1orf56): names are compared upper-cased and the rules above apply after upper-casing, so names of two IDs
that differ only by case are ambiguous, and two of our symbols that differ only by case are flagged
(``case_collisions``) and never translated. Rows other than ``symbol`` hold the upper-cased name. Names that resolve to an HGNC ID we do not measure are not written: they can
match no measured gene. Gene-set library members are translated through the table when a library loads
(``analysis.pathway.cache``), except CellMarker's mouse sets, whose members are upper-cased mouse symbols.
"""

from __future__ import annotations

from pathlib import Path

import polars as pl

ROOT = Path(__file__).resolve().parents[2]
ALIASES_PATH = ROOT / "data" / "external" / "vendor_assay_tables" / "hgnc_aliases.tsv"
# HGNC complete set, the first monthly archive after UniProt 2026_03 (a dated, stable public URL): locus
# types, HGNC IDs, previous and alias symbols.
HGNC_RELEASE = "2026-09-04"
HGNC_URL = (
    "https://storage.googleapis.com/public-download-files/hgnc/archive/archive/monthly/tsv/"
    f"hgnc_complete_set_{HGNC_RELEASE}.tsv"
)
HGNC_SHA256 = "6f43d6ff43aa9fdfa5fb2f20a20a7cace66e6e02e2a0dcf19d9b726e2e248d20"
HGNC_PATH = ROOT / "data" / "external" / "hgnc" / f"hgnc_complete_set_{HGNC_RELEASE}.tsv"
COLUMNS = ("name", "kind", "hgnc_id", "symbol", "hgnc_release")
SYMBOL, APPROVED, PREVIOUS, ALIAS, AMBIGUOUS = "symbol", "approved", "previous", "alias", "ambiguous"


def _names(col: str) -> pl.Expr:
    return pl.col(col).fill_null("").str.strip_chars('"').str.split("|").list.eval(
        pl.element().filter(pl.element() != "")
    )


def read_hgnc_names(path: Path) -> pl.DataFrame:
    """``hgnc_id``, ``symbol``, ``prev_symbol`` and ``alias_symbol`` (lists) of the HGNC complete set."""
    table = pl.read_csv(path, separator="\t", infer_schema_length=0, quote_char=None)
    return table.select("hgnc_id", "symbol", _names("prev_symbol").alias("prev_symbol"), _names("alias_symbol").alias("alias_symbol"))


def symbol_ids_from_hgnc(symbols, hgnc: pl.DataFrame) -> dict[str, str]:
    """Our symbol -> its HGNC ID, from the HGNC release alone.

    An approved symbol takes its ID. Otherwise a previous symbol of exactly one ID takes that ID, unless
    the ID is already another of our symbols' (GOLGA6L3, a previous symbol of our GOLGA6L3P, takes none);
    this is how a symbol that HGNC has renamed gets its ID. Any other
    name (Olink codes, HERVK-113) has none.

    Args:
        symbols: Our gene symbols.
        hgnc: ``read_hgnc_names``.
    """
    symbols = sorted(set(symbols))
    approved = dict(hgnc.select("symbol", "hgnc_id").iter_rows())
    previous: dict[str, set[str]] = {}
    for hgnc_id, names in hgnc.select("hgnc_id", "prev_symbol").iter_rows():
        for name in names:
            previous.setdefault(name, set()).add(hgnc_id)
    out = {s: approved[s] for s in symbols if s in approved}
    taken = set(out.values())
    for s in symbols:
        if s not in out and len(previous.get(s, ())) == 1:
            (hgnc_id,) = previous[s]
            if hgnc_id not in taken:
                out[s] = hgnc_id
    return dict(sorted(out.items()))


def build_alias_table(hgnc: pl.DataFrame, ours: dict[str, str], release: str) -> pl.DataFrame:
    """The alias table (``COLUMNS``) for our symbols, every name resolved case-insensitively.

    Names are compared upper-cased (Enrichr upper-cases every symbol: C1ORF56 for our C1orf56), and every
    rule applies after upper-casing: names of two HGNC IDs that differ only by case (Car1 for CA1, CAR1 for
    NR1I3) are ambiguous. ``symbol`` rows keep our exact spelling; the other rows hold the upper-cased name.
    Two of our symbols that differ only by case keep their ``symbol`` rows (their HGNC IDs) but are never
    translated (``case_collisions``).

    Args:
        hgnc: ``read_hgnc_names``.
        ours: Our gene symbol -> its HGNC ID (``assay_gene_updates.symbol_hgnc_ids``).
        release: The HGNC release, written on every row.

    Raises:
        ValueError: When one of our symbols is, ignoring case, the approved symbol of an ID that is not ours.
    """
    approved: dict[str, set[str]] = {}
    for symbol, hgnc_id in hgnc.select("symbol", "hgnc_id").iter_rows():
        approved.setdefault(symbol.upper(), set()).add(hgnc_id)
    ours_by_key: dict[str, set[str]] = {}
    for symbol, hgnc_id in ours.items():
        ours_by_key.setdefault(symbol.upper(), set()).add(hgnc_id)
    clash = {k: sorted(approved[k] - ids) for k, ids in ours_by_key.items() if approved.get(k, set()) - ids}
    if clash:
        raise ValueError(f"our symbols that are, ignoring case, another gene's approved HGNC symbol: {clash}")
    by_kind: dict[str, dict[str, set[str]]] = {PREVIOUS: {}, ALIAS: {}}
    for hgnc_id, previous, aliases in hgnc.select("hgnc_id", "prev_symbol", "alias_symbol").iter_rows():
        for kind, names in ((PREVIOUS, previous), (ALIAS, aliases)):
            for name in names:
                by_kind[kind].setdefault(name.upper(), set()).add(hgnc_id)
    our_symbol = {i: s for s, i in ours.items()}
    rows = [(s, SYMBOL, i, s) for s, i in sorted(ours.items())]
    for key in sorted(set(approved) | set(by_kind[PREVIOUS]) | set(by_kind[ALIAS])):
        if key in ours_by_key:
            continue
        if key in approved:
            kind, ids = APPROVED, approved[key]
        elif key in by_kind[PREVIOUS]:
            kind, ids = PREVIOUS, by_kind[PREVIOUS][key]
        else:
            kind, ids = ALIAS, by_kind[ALIAS][key]
        if len(ids) == 1:
            (hgnc_id,) = ids
            if hgnc_id in our_symbol:
                rows.append((key, kind, hgnc_id, our_symbol[hgnc_id]))
        elif ids & set(our_symbol):
            rows.append((key, AMBIGUOUS, "|".join(sorted(ids)), None))
    return pl.DataFrame(
        [(*r, release) for r in rows], schema=dict.fromkeys(COLUMNS, pl.String), orient="row"
    )


def case_collisions(table: pl.DataFrame) -> dict[str, list[str]]:
    """Upper-cased name -> our symbols that differ only by case (flagged; never translated)."""
    symbols = table.filter(pl.col("kind") == SYMBOL)["symbol"].to_list()
    by_key: dict[str, list[str]] = {}
    for symbol in sorted(symbols):
        by_key.setdefault(symbol.upper(), []).append(symbol)
    return {k: v for k, v in by_key.items() if len(v) > 1}


def write_alias_table(table: pl.DataFrame, path: Path = ALIASES_PATH) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    table.write_csv(path, separator="\t")


def read_aliases(path: Path = ALIASES_PATH) -> pl.DataFrame:
    """The generated alias table (stage ``vendor_assay_tables``), every column as text (an empty field is null)."""
    return pl.read_csv(path, separator="\t", infer_schema_length=0)


def symbol_translation(table: pl.DataFrame) -> dict[str, str]:
    """Upper-cased name -> our exact symbol, for every name the table resolves.

    Ambiguous names and our case-colliding symbols (``case_collisions``) are absent, so they stay as they are.
    """
    blocked = set(case_collisions(table))
    out: dict[str, str] = {}
    for name, symbol in table.filter(pl.col("kind") != AMBIGUOUS).select("name", "symbol").iter_rows():
        key = name.upper()
        if key in blocked:
            continue
        if out.get(key, symbol) != symbol:
            raise ValueError(f"alias table resolves {key} to {out[key]} and {symbol}")
        out[key] = symbol
    return out


def hgnc_ids(table: pl.DataFrame) -> dict[str, str]:
    """Our symbol -> its HGNC ID."""
    return dict(table.filter(pl.col("kind") == SYMBOL).select("symbol", "hgnc_id").iter_rows())


def translate(members: list[str], translation: dict[str, str]) -> list[str]:
    """Members renamed to our symbols where the table resolves them (matched upper-cased), in order, each once."""
    return list(dict.fromkeys(translation.get(m.upper(), m) for m in members))
